    protected void createGenModelAnnotations() {
        String source = "http://www.eclipse.org/emf/2002/GenModel";
        this.addAnnotation((ENamedElement)this.abstractSignalEClass, source, new String[]{"documentation", "A single signal or a signal group (XOR). "});
        this.addAnnotation((ENamedElement)this.communicationDirectionTypeEEnum, source, new String[]{"documentation", "Describes the communication direction. "});
        this.addAnnotation((ENamedElement)this.communicationDirectionTypeEEnum.getELiterals().get(0), source, new String[]{"documentation", "reception (Input)"});
        this.addAnnotation((ENamedElement)this.communicationDirectionTypeEEnum.getELiterals().get(1), source, new String[]{"documentation", "Transmission (Output)"});
        this.addAnnotation((ENamedElement)this.dcmIPduEClass, source, new String[]{"documentation", "Represents the I-PDU's handled by Dcm. "});
        this.addAnnotation((ENamedElement)this.iPduEClass, source, new String[]{"documentation", "The IPdu (Interaction Layer Protocol Data Unit) element is used to sum up the IPdus of AUTOSAR COM, DCM and IPduM. These Pdus are routed by the PduR. \r\n\r\nIn the AUTOSAR Layered Archtecture the NPdu is not a spezialisation of an IPdu. The NPdu is located under the IPdu to support the low-level routing of NPdu's. More details can be found in the NPdu class description. "});
        this.addAnnotation((ENamedElement)this.getIPdu_Length(), source, new String[]{"documentation", "The size of the IPDU in bits. "});
        this.addAnnotation((ENamedElement)this.getIPdu_UnusedBitPattern(), source, new String[]{"documentation", "AUTOSAR COM fills not used areas of an IPDU with this bit-pattern. This attribute is mandatory to avoid undefined behavior. This byte-pattern will be repeated throughout the IPDU."});
        this.addAnnotation((ENamedElement)this.pduEClass, source, new String[]{"documentation", "Collection of all Pdus that can be routed through a bus interface.  "});
        this.addAnnotation((ENamedElement)this.dynamicPartEClass, source, new String[]{"documentation", "Dynamic part of a multiplexed I-Pdu. \r\nReserved space which is used to transport varying SignalIPdus at the same position, controlled by the corresponding selectorFieldCode."});
        this.addAnnotation((ENamedElement)this.getDynamicPart_DynamicPartAlternatives(), source, new String[]{"documentation", "Com IPdu alternatives that are transmitted  in the Dynamic Part of the MultiplexedIPdu."});
        this.addAnnotation((ENamedElement)this.multiplexedPartEClass, source, new String[]{"documentation", "The StaticPart and the DynamicPart have common properties. Both can be separated in multiple segments within the multiplexed PDU."});
        this.addAnnotation((ENamedElement)this.getMultiplexedPart_SegmentPositions(), source, new String[]{"documentation", "The StaticPart and the DynamicPart can be separated in multiple segments within the multiplexed PDU. Therefore the StaticPart and the DynamicPart can contain multiple SegmentPositions."});
        this.addAnnotation((ENamedElement)this.segmentPositionEClass, source, new String[]{"documentation", "The StaticPart and the DynamicPart can be separated in multiple segments within the multiplexed PDU. \r\n\r\nThe ISignalIPdus are copied bit by bit into the MultiplexedIPdu. If the space of the first segment is 5 bits large than the first 5 bits of the ISignalIPdu are copied into this first segment and so on."});
        this.addAnnotation((ENamedElement)this.getSegmentPosition_SegmentByteOrder(), source, new String[]{"documentation", "This attribute defines the order of the bytes of the segment and the packing into the MultiplexedIPdu. The byte ordering \"Little Endian\" (MostSignificantByteLast) and \"Big Endian\" (MostSignificantByteFirst) can be selected.\r\n\r\nA mix between Little Endian and Big Endian within a MultiplexedIPdu (staticPart, dynamicPart, selectorField) is not allowed. \r\n"});
        this.addAnnotation((ENamedElement)this.getSegmentPosition_SegmentLength(), source, new String[]{"documentation", "Data Length of the segment in bits. "});
        this.addAnnotation((ENamedElement)this.getSegmentPosition_SegmentPosition(), source, new String[]{"documentation", "Segments bit position relatively to the beginning of a multiplexed IPdu.\r\n\r\nNote that the absolute position of the segment in the MultiplexedIPdu is determined by the definition of the segmentByteOrder attribute of the SegmentPosition. If Big Endian is specified, the start position indicates the bit position of the most significant bit in the IPdu. If Little Endian is specified, the start position indicates the bit position of the least significant bit in the IPdu.\r\n"});
        this.addAnnotation((ENamedElement)this.dynamicPartAlternativeEClass, source, new String[]{"documentation", "One of the Com IPdu alternatives that are transmitted in the Dynamic Part of the MultiplexedIPdu. The selectorFieldCode specifies which Com IPdu is contained in the DynamicPart within a certain transmission of a multiplexed PDU."});
        this.addAnnotation((ENamedElement)this.getDynamicPartAlternative_IPdu(), source, new String[]{"documentation", "Reference to a Com IPdu which is routed to the IPduM module and is combined to a multiplexedPdu. "});
        this.addAnnotation((ENamedElement)this.getDynamicPartAlternative_InitialDynamicPart(), source, new String[]{"documentation", "Dynamic part that shall be used to initialize this multiplexed IPdu.\r\n\r\nConstraint: Only one \"DynamicPartAlternative\" in a \"DynamicPart\" shall be the initialDynamicPart."});
        this.addAnnotation((ENamedElement)this.getDynamicPartAlternative_SelectorFieldCode(), source, new String[]{"documentation", "The selector field is part of a multiplexed IPdu. It consists of contiguous bits. The value of the selector field selects the layout of the dynamic part of the IPdu. "});
        this.addAnnotation((ENamedElement)this.signalIPduEClass, source, new String[]{"documentation", "Represents the I-PDU's handled by Com. \r\nThe SignalIPdu assembled and disassembled in AUTOSAR COM consists of one or more signals.\r\n\r\nIn case no multiplexing is performed this IPdu is routed to/from the Interface Layer."});
        this.addAnnotation((ENamedElement)this.getSignalIPdu_IPduTimingSpecification(), source, new String[]{"documentation", "Timing specification for Com IPdus (Transmission Modes). "});
        this.addAnnotation((ENamedElement)this.getSignalIPdu_SignalToPduMappings(), source, new String[]{"documentation", "Definition of SignalToIPduMappings included in the SignalIPdu. "});
        this.addAnnotation((ENamedElement)this.iSignalToIPduMappingEClass, source, new String[]{"documentation", "An ISignalToIPduMapping describes the mapping of ISignals to ISignalIPdus and defines the position of the ISignal within an ISignalIPdu.\r\n\r\nThis element does NOT describe signal or IPdu fan-out but is used to describe the COM Signal Gateway fan-out.  \r\nIn case the ISignal/ISignalGroup is not part of the Signal Gateway the\r\nISignal/ISignalGroup can only be mapped into one ISignalIPdu.\r\nIn case the ISignal/ISignalGroup is part of the Signal Gateway several\r\nISignalToIPduMappings of the same ISignal are supported.\r\n"});
        this.addAnnotation((ENamedElement)this.getISignalToIPduMapping_PackingByteOrder(), source, new String[]{"documentation", "This parameter defines the order of the bytes of the signal and the packing into the SignalIPdu. The byte ordering \"Little Endian\" (MostSignificantByteLast) and \"Big Endian\" (MostSignificantByteFirst) can be selected. \r\nThe value of this attribute impacts the absolute position of the signal into the SignalIPdu (see the startPosition attribute description). \r\n"});
        this.addAnnotation((ENamedElement)this.getISignalToIPduMapping_Signal(), source, new String[]{"documentation", "Reference to a ISignal that is mapped into the SignalIPdu. \r\n\r\nSeveral ISignalToPduMappings to the same ISignal are only relevant when the ECU handles the signal gateway. "});
        this.addAnnotation((ENamedElement)this.getISignalToIPduMapping_StartPosition(), source, new String[]{"documentation", "This parameter is necessary to describe the bitposition of a signal within an SignalIPdu.\r\nIt denotes the least significant bit for \"Little Endian\" and the most significant bit for \"Big Endian\" packed signals within the IPdu (see the description of the packingByteOrder attribute).\r\n\r\nBits within the IPdu are counted as follows (see the OSEK COM v3.0.3 specification) :\r\n      Bit 0 corresponds to Byte 0 Bit 0\r\n      Bit 1 corresponds to Byte 0 Bit 1\r\n      .....\r\n      Bit 8 corresponds to Byte 1 Bit 0\r\n      etc.\r\n\r\nPlease note that the way the bytes will be actually sent on the bus does not impact this representation: they will always be seen by the software as a byte array. \r\nNote also that the absolute position of the signal in the SignalIPdu is then determined by the definition of the packingByteOrder attribute of the signal.\r\n\r\nIf a mapping for the SystemSignalGroup is defined, only the UpdateIndicationBitPosition is relevant, and the startPosition shall be ignored. "});
        this.addAnnotation((ENamedElement)this.getISignalToIPduMapping_TransferProperty(), source, new String[]{"documentation", "The triggered, triggeredOnChange, triggeredWithoutRepetition and triggeredOnChangeWithoutRepetition transferProperty causes immediate transmission of the IPdu, except if transmission mode Periodic or transmission mode NONE is defined for the IPdu. The Pending transfer property does not cause transmission of an IPdu.\r\n\r\nThe immediate transmission of the IPdu is caused even if only one Signal of an IPdu has the transferProperty triggered, triggeredWithoutRepetition, triggeredOnChange, triggeredOnChangeWithoutRepetition and all other Signals have the transferProperty pending.\r\n\r\nAlso for ISignals which refer to GroupSignals of a SystemSignalGroup this attribute is relevant and shall be evaluated:\r\n- If none of the ISignals belonging to the GroupSignals of a SystemSignalGroup have a transferProperty defined the transferProperty of the ISignal referring to the SystemSignalGroup is considered.\r\n- If at least one of the ISignals belonging to the GroupSignals of a SystemSignalGroup has a transferProperty defined all ISignals belonging to the GroupSignals of a SystemSignalGroup shall have a transferProperty defined as well. All of the transferProperties of the ISignals belonging to the GroupSignals of a SystemSignalGroup are considered."});
        this.addAnnotation((ENamedElement)this.getISignalToIPduMapping_UpdateIndicationBitPosition(), source, new String[]{"documentation", "The UpdateIndicationBit indicates to the receivers that the signal (or the signal group) was updated by the sender. Length is always one bit. The UpdateIndicationBitPosition attribute describes the position of the update bit within the SignalIPdu. \r\n\r\nThe updateIndicationBitPosition is determined by the definition of the packingByteOrder attribute. If Big Endian is specified, the updateIndicationBitPosition indicates the bit position of the most significant bit in the ISignalIPdu. If Little Endian is specified, the updateIndicationBitPosition indicates the bit position of the least significant bit in the ISignalIPdu. \r\n"});
        this.addAnnotation((ENamedElement)this.transferPropertyEnumEEnum, source, new String[]{"documentation", "Transfer Properties of a Signal. "});
        this.addAnnotation((ENamedElement)this.transferPropertyEnumEEnum.getELiterals().get(0), source, new String[]{"documentation", "The signal in the assigned IPdu is updated and a request for the IPdu's transmission is made."});
        this.addAnnotation((ENamedElement)this.transferPropertyEnumEEnum.getELiterals().get(1), source, new String[]{"documentation", "If the signal has the TransferProperty pending, then the function Com_SendSignal shall not perform a transmission of the IPdu associated with the signal."});
        this.addAnnotation((ENamedElement)this.transferPropertyEnumEEnum.getELiterals().get(2), source, new String[]{"documentation", "The signal in the assigned IPdu is updated and a request for the IPdus transmission is made only if the signal value is different from the already stored signal value."});
        this.addAnnotation((ENamedElement)this.transferPropertyEnumEEnum.getELiterals().get(3), source, new String[]{"documentation", "The signal in the assigned IPdu is updated and a request for the IPdu's transmission is made. In the DIRECT/N-TIMES or MIXED transmission mode (EventControlledTiming) the IPdu will be transmitted just once without a repetition, independent of the defined NumberOfRepeats."});
        this.addAnnotation((ENamedElement)this.transferPropertyEnumEEnum.getELiterals().get(4), source, new String[]{"documentation", "The signal in the assigned IPdu is updated and a request for the IPdus transmission is made only if the signal value is different from the already stored signal value.  In the DIRECT/N-TIMES or MIXED transmission mode (EventControlledTiming) the IPdu will be transmitted just once without a repetition, independent of the defined NumberOfRepeats."});
        this.addAnnotation((ENamedElement)this.iSignalEClass, source, new String[]{"documentation", "Signal of the Interaction Layer. The RTE supports a \"signal fan-out\" where the same System Signal is sent in different SignalIPdus to multiple receivers. \r\n\r\nThe System Signal is unique per System. To support the RTE \"signal fan-out\" each SignalIPdu  contains ISignals. If the same System Signal is to be mapped into several SignalIPdus there is one ISignal needed for each ISignalToIPduMapping. \r\n\r\nISignals describe the Interface between the Precompile configured RTE and the potentially Postbuild configured Com Stack (see ECUC Parameter Mapping). \r\n\r\nIn the case of the SystemSignalGroup an ISignal must be created for the SystemSignalGroup and for each SystemSignal contained in the SystemSignalGroup.\r\nIf a mapping for the SystemSignalGroup is defined, only the UpdateIndicationBitPosition is relevant, and the startPosition shall be ignored. "});
        this.addAnnotation((ENamedElement)this.getISignal_SystemSignal(), source, new String[]{"documentation", "Reference to the System Signal that is supposed to be transmitted in the ISignal. "});
        this.addAnnotation((ENamedElement)this.iPduTimingEClass, source, new String[]{"documentation", "AUTOSAR COM provides the possibility to define two different TRANSMISSION MODES for each I-PDU.\r\n\r\nThe Transmission Mode of an I-PDU that is valid at a specific point in time is \r\nselected using the values of the signals that are mapped to this I-PDU. For each I-PDU a Transmission Mode Selector is defined. The Transmission Mode Selector is calculated by evaluating the conditions for a subset of signals  (class TransmissionModeCondition in the System Template).\r\n\r\nThe Transmission Mode Selector is defined to be true, if at least one Condition evaluates to true and is defined to be false, if all Conditions evaluate to false. "});
        this.addAnnotation((ENamedElement)this.getIPduTiming_CyclicTiming(), source, new String[]{"documentation", "If the COM Transmission Mode is true the timing can be aggregated directly by the IPduTriggering.\r\n\r\nAdditionally a Cyclic Timing can be defined as a Timing Requirement (for Lin, FlexRay). Timing Requirements are aggregated by the IPduTriggering/IPduTiming  element."});
        this.addAnnotation((ENamedElement)this.getIPduTiming_EventControlledTiming(), source, new String[]{"documentation", "If the COM Transmission Mode is true the timing can be aggregated directly by the IPduTiming.\r\n\r\nAdditionally an EventControlledTiming can be defined as a Timing Requirement (for Lin, FlexRay). Timing Requirements are aggregated by the IPduTriggering/IPduTiming element."});
        this.addAnnotation((ENamedElement)this.getIPduTiming_MinimumDelay(), source, new String[]{"documentation", "Minimum Delay in seconds between successive transmissions of this I-PDU, independent of the Transmission Mode. "});
        this.addAnnotation((ENamedElement)this.getIPduTiming_RequestControlledTiming(), source, new String[]{"documentation", "A RequestControlled Timing can be defined as a Timing Requirement. \r\n\r\nTiming Requirements are aggregated by the IPduTriggering/IPduTiming element."});
        this.addAnnotation((ENamedElement)this.getIPduTiming_TransmissionModeDeclaration(), source, new String[]{"documentation", "AUTOSAR COM allows configuring statically two different transmission modes for each I-PDU (True and False). The Transmission Mode Selector evaluates the conditions for a subset of signals and decides the transmission mode. It is possible to switch between the transmission modes during runtime.\r\n\r\nIn case only the TRUE transmission mode is used there is no need for the \"TransmissionModeDeclaration\" and its sub-structure."});
        this.addAnnotation((ENamedElement)this.frameEClass, source, new String[]{"documentation", "Data frame which is sent over a communication medium. This element describes the pure Layout of a frame sent on a channel."});
        this.addAnnotation((ENamedElement)this.getFrame_FrameLength(), source, new String[]{"documentation", "The used length (in bytes)  of the referencing frame. Should not be confused with a static byte length reserved for each frame by some platforms (e.g. FlexRay). "});
        this.addAnnotation((ENamedElement)this.getFrame_PduToFrameMappings(), source, new String[]{"documentation", "A frames layout as a sequence of Pdus.\r\n"});
        this.addAnnotation((ENamedElement)this.pduToFrameMappingEClass, source, new String[]{"documentation", "A PduToFrameMapping defines the composition of Pdus in each frame. \r\n\r\nDepending on its relation to entities such channels and clusters it can be unambiguously deduced whether a fan-out is handled by the Pdu router or the Bus Interface. \r\n"});
        this.addAnnotation((ENamedElement)this.getPduToFrameMapping_PackingByteOrder(), source, new String[]{"documentation", "This attribute defines the order of the bytes of the Pdu and the packing into the Frame. The byte ordering \"Little Endian\" (MostSignificantByteLast) and \"Big Endian\" (MostSignificantByteFirst) can be selected.\r\n\r\nA mix between Little Endian and Big Endian within a Frame is not allowed (all PduToFrameMappings within a Frame must have the same packingByteOrder). \r\n"});
        this.addAnnotation((ENamedElement)this.getPduToFrameMapping_Pdu(), source, new String[]{"documentation", "Reference to a I-Pdu, N-Pdu or NmPdu that is transmitted in the Frame. "});
        this.addAnnotation((ENamedElement)this.getPduToFrameMapping_StartPosition(), source, new String[]{"documentation", "This parameter is necessary to describe the byteposition of a Pdu within a Frame.\r\n\r\nNote that the absolute position of the Pdu in the Frame is determined by the definition of the packingByteOrder attribute. If Big Endian is specified, the start position indicates the bit position of the most significant bit in the Frame. If Little Endian is specified, the start position indicates the bit position of the least significant bit in the Frame. \r\n"});
        this.addAnnotation((ENamedElement)this.getPduToFrameMapping_UpdateIndicationBitPosition(), source, new String[]{"documentation", "Indication to the receivers that the corresponding I-Pdu was updated by the sender. \r\nThis attribute describes the position of the update bit in the frame that aggregates this PDUToFrameMapping. Length is always one bit.\r\n\r\nThe updateIndicationBitPosition is determined by the definition of the packingByteOrder attribute. If Big Endian is specified, the updateIndicationBitPosition indicates the bit position of the most significant bit in the Frame. If Little Endian is specified, the updateIndicationBitPosition indicates the bit position of the least significant bit in the Frame. \r\n"});
        this.addAnnotation((ENamedElement)this.framePortEClass, source, new String[]{"documentation", "Connectors reception or send port on the referenced channel referenced by a FrameTriggering."});
        this.addAnnotation((ENamedElement)this.iPduGroupEClass, source, new String[]{"documentation", "The AUTOSAR COM Layer is able to start and to stop sending and receiving  configurable groups of I-Pdus during runtime. An I-Pdu group contains either Com I-Pdus or I-Pdu groups.\r\n\r\nWhen an I-Pdu group containing one or more other I-Pdu groups is started the contained I-Pdu groups shall also be started. When an I-Pdu group containing one or more other I-Pdu groups is stopped the contained I-Pdu groups shall also be stopped.\r\n\r\nOnly a two level hierarchy of I-Pdu groups is allowed. An I-Pdu group that is part of an I-Pdu group must not contain I-Pdu groups.\r\n\r\nIn the COM SRS document it is stated that \"every IPdu must belong to exactly 1 I-Pdu group.\"\r\nThis is true from a dedicated ECUs point of view, however in the system description handling a number of ECUs several IPdu Groups may reference to the same SignalIPdu."});
        this.addAnnotation((ENamedElement)this.getIPduGroup_CommunicationDirection(), source, new String[]{"documentation", "This attribute determines in which direction IPdus that are contained in this IPduGroup will be transmitted (communication direction can be either Send or Receive)."});
        this.addAnnotation((ENamedElement)this.getIPduGroup_CommunicationMode(), source, new String[]{"documentation", "This attribute defines the use-case for this IPduGroup (e.g. diagnostic, debugging etc.). For example, in a diagnostic mode all IPdus - which are not involved in diagnostic - are disabled. The use cases are not limited to a fixed enumeration and can be specified as a string. "});
        this.addAnnotation((ENamedElement)this.getIPduGroup_ContainedIPduGroups(), source, new String[]{"documentation", "An I-PDU group can be included in other I-Pdu groups."});
        this.addAnnotation((ENamedElement)this.getIPduGroup_IPdus(), source, new String[]{"documentation", "Reference to a set of SignalIPdus, which are contained in the I-Pdu Group."});
        this.addAnnotation((ENamedElement)this.iPduPortEClass, source, new String[]{"documentation", "Connectors reception or send port on the referenced channel referenced by an IPduTriggering."});
        this.addAnnotation((ENamedElement)this.iPduTriggeringEClass, source, new String[]{"documentation", "The IPduTriggering describes on which channel the IPdu is transmitted.\r\n\r\nDepending on its relation to entities such channels and clusters it can be unambiguously deduced whether a fan-out is handled by the Pdu router or the Bus Interface. \r\n\r\nIf the fan-out is specified between different clusters it shall be handled by the Pdu Router.\r\nIf the fan-out is specified between different channels of the same cluster it shall be handled by the Bus Interface.\r\n"});
        this.addAnnotation((ENamedElement)this.getIPduTriggering_IPduPorts(), source, new String[]{"documentation", "This relationship specifies explicitly which IPdus are received/sent by the connected ECU on the connected channel.\r\n\r\nThis reference shall be provided to every IPduPort on every ECU in the System which sends and/or receives the IPdu. "});
        this.addAnnotation((ENamedElement)this.getIPduTriggering_IPdu(), source, new String[]{"documentation", "Reference to the Pdu for which the IPdu triggering is defined. One IPdu can be triggered on different channels. The Pdu routing by the PduR is only allowed for IPdus and not for NmPdus and UserDefinedPdus. Nevertheless is the reference to the Pdu element necessary since the PduTriggering element is also used to specify the sending and receiving connections to EcuPorts.\r\n"});
        this.addAnnotation((ENamedElement)this.getIPduTriggering_ISignalTriggerings(), source, new String[]{"documentation", "This reference provides the relationship to the ISignalTriggerings that are implemented by the IPduTriggering. The reference is optional since no ISignalTriggering can be defined for DCM and Multiplexed Pdus. "});
        this.addAnnotation((ENamedElement)this.getIPduTriggering_TimingRequirement(), source, new String[]{"documentation", "Describes timing requirements on an I-PDU, handled by the bus interface, (Flexray or LIN). \r\nFor CAN the timing information must be equal to the timing specification on a signal IPdu.\r\n"});
        this.addAnnotation((ENamedElement)this.iSignalTriggeringEClass, source, new String[]{"documentation", "A ISignalTriggering defines the manner of triggering of a ISignal on the channel, on which it is sent.\r\n\r\nISignalTriggering should only be used for defining timing constraints. Com does not know of signals related to a specific cluster or channel.\r\n"});
        this.addAnnotation((ENamedElement)this.getISignalTriggering_CyclicTiming(), source, new String[]{"documentation", "Specification of a cyclic sending behavior."});
        this.addAnnotation((ENamedElement)this.getISignalTriggering_EventControlledTiming(), source, new String[]{"documentation", "Specification of a event driven sending behavior. "});
        this.addAnnotation((ENamedElement)this.getISignalTriggering_ISignalPorts(), source, new String[]{"documentation", "This relationship allows to specify explicitly which ISignals are received/sent by the connected ECU on the connected channel.\r\n\r\nThis reference shall be provided to every SignalPort on every ECU in the System which sends and/or receives the Signal. "});
        this.addAnnotation((ENamedElement)this.getISignalTriggering_Signal(), source, new String[]{"documentation", "Reference to the ISignal for which the ISignalTriggering is defined."});
        this.addAnnotation((ENamedElement)this.signalPortEClass, source, new String[]{"documentation", "Connectors reception or send port on the referenced channel referenced by an ISignalTriggering.\r\n\r\nIf different timeouts or DataFilters for ISignals need to be specified several ISignalPorts may be created.\r\n"});
        this.addAnnotation((ENamedElement)this.getSignalPort_DataFilter(), source, new String[]{"documentation", "Optional specification of  a signal COM filter at the receiver side in case that  the System Description doesn't use a complete Software Component Description (VFB View). This supports the inclusion of legacy system signals. If a full DataMapping exist for the SystemSignal this information may be available from a configured ReceiverComSpec. In this case the ReceiverComSpec overrides this optional specification.  \r\n\r\n"});
        this.addAnnotation((ENamedElement)this.getSignalPort_Timeout(), source, new String[]{"documentation", "Optional timeout value in seconds for the reception of the ISignal.\r\nIn case the System Description doesn't use a complete Software Component Description (VFB View). This supports the inclusion of legacy system signals.\r\n\r\nIf a full DataMapping exist for the SystemSignal this information may be available from a configured ReceiverComSpec, in this case the timeout value in ReceiverComSpec override this optional timeout specification. "});
        this.addAnnotation((ENamedElement)this.multiplexedIPduEClass, source, new String[]{"documentation", "A MultiplexedPdu (i.e. NOT a COM I-PDU) contains a DynamicPart, an optional StaticPart and a selectorField. In case of multiplexing this IPdu is routed between the Pdu Multiplexer and the Interface Layer.\r\n\r\nA multiplexer is used to define variable parts within an IPdu that may carry different signals. The receivers of such a IPdu can determine which signalPdus are transmitted by evaluating the selector field, which carries a unique selector code for each sub-part.  "});
        this.addAnnotation((ENamedElement)this.getMultiplexedIPdu_DynamicPart(), source, new String[]{"documentation", "According to the value of the selector field some parts of the IPdu have a different layout.  "});
        this.addAnnotation((ENamedElement)this.getMultiplexedIPdu_SelectorFieldByteOrder(), source, new String[]{"documentation", "This attribute defines the order of the bytes of the selectorField and the packing into the MultiplexedIPdu. The byte ordering \"Little Endian\" (MostSignificantByteLast) and \"Big Endian\" (MostSignificantByteFirst) can be selected.\r\nA mix between Little Endian and Big Endian within a MultiplexedIPdu (staticPart, dynamicPart, selectorField) is not allowed. \r\n"});
        this.addAnnotation((ENamedElement)this.getMultiplexedIPdu_SelectorFieldLength(), source, new String[]{"documentation", "The size in bits of the selector field shall be configurable in a range of one bit and eight bits. "});
        this.addAnnotation((ENamedElement)this.getMultiplexedIPdu_SelectorFieldStartPosition(), source, new String[]{"documentation", "This parameter is necessary to describe the position of the selector field within the IPdu.\r\n\r\nNote that the absolute position of the selectorField in the MultiplexedIPdu is determined by the definition of the selectorFieldByteOrder attribute of the Multiplexed Pdu. If Big Endian is specified, the start position indicates the bit position of the most significant bit in the IPdu. If Little Endian is specified, the start position indicates the bit position of the least significant bit in the IPdu.\r\n"});
        this.addAnnotation((ENamedElement)this.getMultiplexedIPdu_StaticPart(), source, new String[]{"documentation", "The static part of the multiplexed IPdu is the same regardless of the selector field. The static part is optional. "});
        this.addAnnotation((ENamedElement)this.getMultiplexedIPdu_TriggerMode(), source, new String[]{"documentation", "IPduM can be configured to send a transmission request for the new multiplexed I-PDU to the PDU-Router because of the trigger conditions/ modes that are described in the TriggerMode enumeration."});
        this.addAnnotation((ENamedElement)this.triggerModeEEnum, source, new String[]{"documentation", "IPduM can be configured to send a transmission request for the new multiplexed I-PDU to the PDU-Router because of conditions/ modes."});
        this.addAnnotation((ENamedElement)this.triggerModeEEnum.getELiterals().get(0), source, new String[]{"documentation", "IPduM does not trigger transmission because of receiving anything of this IPdu in case of TriggerTransmit. "});
        this.addAnnotation((ENamedElement)this.triggerModeEEnum.getELiterals().get(1), source, new String[]{"documentation", "IPduM sends a transmission request to the PduR if a static part is received."});
        this.addAnnotation((ENamedElement)this.triggerModeEEnum.getELiterals().get(2), source, new String[]{"documentation", "IPduM sends a transmission request to the PduR if a dynamic part is received."});
        this.addAnnotation((ENamedElement)this.triggerModeEEnum.getELiterals().get(3), source, new String[]{"documentation", "IPduM sends a transmission request to the PduR if a static or dynamic part is received."});
        this.addAnnotation((ENamedElement)this.staticPartEClass, source, new String[]{"documentation", "Some parts/signals of the I-PDU may be the same regardless of the selector field. Such a part is called static part. The static part is optional. "});
        this.addAnnotation((ENamedElement)this.getStaticPart_IPdu(), source, new String[]{"documentation", "Reference to a Com IPdu which is routed to the IPduM module and is combined to a multiplexedPdu. "});
        this.addAnnotation((ENamedElement)this.nmPduEClass, source, new String[]{"documentation", "Network Management I-Pdu"});
        this.addAnnotation((ENamedElement)this.getNmPdu_ISignalToIPduMappings(), source, new String[]{"documentation", "This optional aggregation is used to describe NmUserData that is transmitted in the NmPdu.\r\n"});
        this.addAnnotation((ENamedElement)this.getNmPdu_Length(), source, new String[]{"documentation", "The size of the NmPDU in bits. "});
        this.addAnnotation((ENamedElement)this.getNmPdu_NmCbvPosition(), source, new String[]{"documentation", "Defines the position of the control bit vector within the NM PDU (Bitpositon)."});
        this.addAnnotation((ENamedElement)this.getNmPdu_NmNidPosition(), source, new String[]{"documentation", "Defines the bitposition of the source node identifier within the NM PDU. "});
        this.addAnnotation((ENamedElement)this.getNmPdu_NmUserDataLength(), source, new String[]{"documentation", "Defines the length in Bytes of the user data contained in the NM PDU."});
        this.addAnnotation((ENamedElement)this.nPduEClass, source, new String[]{"documentation", "This is a PDU of the Transport Layer.\r\nThe main purpose of the TP Layer is to segment and reassemble I-PDUs.\r\n\r\nIn case of a Pdu Gateway when the source and the target network are of the same kind (e.g. Can-to-Can routing) it is possible to optimize the routing. The incoming NPdu can be directly forwarded to the PduR and then be sent on the outbound bus without any (resource consuming) TP module involvement. To support this use case the NPdu is located under the IPdu. But in the AUTOSAR Layered Architecture the NPdu is not a specialization of an IPdu. "});
        this.addAnnotation((ENamedElement)this.pdurIPduGroupEClass, source, new String[]{"documentation", "The AUTOSAR PduR will enable and disable the sending of configurable groups of IPdus during runtime according to the AUTOSAR PduR specification.\r\n"});
        this.addAnnotation((ENamedElement)this.getPdurIPduGroup_CommunicationMode(), source, new String[]{"documentation", "This attribute defines the use-case for this PduRIPduGroup. For example, in a diagnostic mode all IPdus - which are not involved in diagnostic - are disabled. The use cases are not limited to a fixed enumeration and can be specified as a string.\r\n"});
        this.addAnnotation((ENamedElement)this.getPdurIPduGroup_IPdus(), source, new String[]{"documentation", "Reference to a set of IPdus, which are contained in the PduR I-Pdu Group.  If an IPdu is routed by the PduR to different destinations (PduR fan-out) than an PduTriggering for each destination is created in the System Template. To enable/disable a specific destination the PdurIPduGroup refers to the PduTriggering.\r\n"});
        this.addAnnotation((ENamedElement)this.systemSignalEClass, source, new String[]{"documentation", "The system signal represents the communication system's view of data exchanged between SW components which reside on different ECUs. The system signals allow to represent this communication in a flattened structure, with exactly one system signal defined for each data element prototype sent and received by connected SW component instances.\r\n \r\nAccording to the COM Specification, signal groups without signals are allowed. These have a \"signalLength\" = 0. In this case there shall be an \"update-bit\" configured. "});
        this.addAnnotation((ENamedElement)this.getSystemSignal_DataType(), source, new String[]{"documentation", "Optional reference to a SystemSignal's datatype in case the System Description doesn't use a complete Software Component Description (VFB View). This supports the inclusion of legacy system signals. \r\n\r\nThis reference can be used to configure the \"ComSignalDataInvalidValue\" and the Data Semantics. \r\n\r\nIf a full DataMapping exist for the SystemSignal this information is additionally available from the mapped DataElement. In this case the referenced datatypes needs to be compatible. "});
        this.addAnnotation((ENamedElement)this.getSystemSignal_InitValue(), source, new String[]{"documentation", "Optional reference to a SystemSignal's initValue in case the System Description doesn't use a complete Software Component Description (VFB View). This supports the inclusion of legacy system signals. \r\n\r\nThis reference can be used to configure the Signal's \"InitValue\". \r\n\r\nIf a full DataMapping exist for the SystemSignal this information may be available from a configured SenderComSpec and ReceiverComSpec. \r\nIn this case the initvalues in SenderComSpec and/or ReceiverComSpec override this optional value specification. Further restrictions apply from the RTE specification. "});
        this.addAnnotation((ENamedElement)this.getSystemSignal_Length(), source, new String[]{"documentation", "Size of the signal in bits. "});
        this.addAnnotation((ENamedElement)this.systemSignalGroupEClass, source, new String[]{"documentation", "A signal group refers to a set of signals that must always be kept together. A signal group is used to guarantee the atomic transfer of AUTOSAR composite data types.  "});
        this.addAnnotation((ENamedElement)this.getSystemSignalGroup_SystemSignals(), source, new String[]{"documentation", "Reference to a set of signals that must always be kept together."});
        this.addAnnotation((ENamedElement)this.userDefinedIPduEClass, source, new String[]{"documentation", "UserDefinedIPdu allows to describe PDU-based communication over Complex Communication Drivers. If a new BSW module is added above the PduR (e.g. a Diagnostic Service ) then this IPdu element shall be used to describe the communication. \r\n"});
        this.addAnnotation((ENamedElement)this.getUserDefinedIPdu_CddType(), source, new String[]{"documentation", "This attribute defines the CDD that transmits or receives the UserDefinedPdu. If several CDDs are defined this attribute is used to distinguish between them. \r\n"});
        this.addAnnotation((ENamedElement)this.userDefinedPduEClass, source, new String[]{"documentation", "UserDefinedPdu allows to describe PDU-based communication over Complex Communication Drivers. If a new BSW module is added above the BusIf (e.g. a new Nm module or XCP) then this Pdu element shall be used to describe the communication. \r\n"});
        this.addAnnotation((ENamedElement)this.getUserDefinedPdu_CddType(), source, new String[]{"documentation", "This attribute defines the CDD that transmits or receives the UserDefinedIPdu. If several CDDs are defined this attribute is used to distinguish between them. \r\n\r\n"});
        this.addAnnotation((ENamedElement)this.frameTriggeringEClass, source, new String[]{"documentation", "The FrameTriggering describes the instance of a frame sent on a channel and defines the manner of triggering (timing information) and identification of a frame on the channel, on which it is sent.\r\n\r\nFor the same frame, if Frame Triggerings exist on more than one channel of the same cluster the fan-out/in is handled by the Bus interface.  "});
        this.addAnnotation((ENamedElement)this.getFrameTriggering_FramePorts(), source, new String[]{"documentation", "This reference allows to specify explicitly which Frame is received/sent by the connected ECU on the connected channel.\r\n\r\nThis reference shall be provided to every FramePort on every ECU in the System which sends and/or receives the Frame. "});
        this.addAnnotation((ENamedElement)this.getFrameTriggering_Frame(), source, new String[]{"documentation", "One frame can be triggered on different channels. If a frame has no frame triggering, it won&rsquo;t be sent at all. A frame triggering has assigned exactly one frame, which it triggers."});
        this.addAnnotation((ENamedElement)this.getFrameTriggering_IPduTriggerings(), source, new String[]{"documentation", "This reference provides the relationship to the IPduTriggerings that are implemented by the FrameTriggering. The reference is optional since no IPduTriggering can be defined for NmPdus. "});
    }

